(6162324, 909496, 108580, '<td valign="top">Very clever concept. I''m not fond of the bra strap and hair stands on the shoulder but a good entry nonetheless.</td>', 'Very clever concept. I''m not fond of the bra strap and hair stands on the shoulder but a good entry nonetheless.', '2010-09-15 01:32:30.000000', NULL, 1),
(6162329, 908757, 33352, '<td valign="top">Halo''s down the left, looks like an Aussie cane fire,nice composition.6</td>', 'Halo''s down the left, looks like an Aussie cane fire,nice composition.6', '2010-09-15 01:44:23.000000', NULL, 1),
