(6162354, 908552, 108990, '<td valign="top">Awesome!</td>', 'Awesome!', '2010-09-15 02:04:28.000000', NULL, 1),
(6162362, 908917, 83313, '<td valign="top">I''ve been fairly flexible on peoples judgment of what is an underexposed photo, but this is clearly OVERexposure, I''m afraid. Plus a bit of camera shake.</td>', 'I''ve been fairly flexible on peoples judgment of what is an underexposed photo, but this is clearly OVERexposure, I''m afraid. Plus a bit of camera shake.', '2010-09-15 02:15:41.000000', NULL, 1),
