(6163155, 908544, 109245, '<td valign="top">This is a beautiful shot, but I don''t think it applies to the challenge.</td>', 'This is a beautiful shot, but I don''t think it applies to the challenge.', '2010-09-15 16:37:50.000000', NULL, 1),
