(6163267, 909345, 108069, '<td valign="top">This is amazing. I''m a bit captivated by this one. It''s so sharp yet so unreal because of the lack of color and the subdued tones that it looks like a toy car, until you notice the rims (and your helpful title). Very cool photo.</td>', 'This is amazing. I''m a bit captivated by this one. It''s so sharp yet so unreal because of the lack of color and the subdued tones that it looks like a toy car, until you notice the rims (and your helpful title). Very cool photo.', '2010-09-15 18:29:36.000000', NULL, 1),
(6163269, 908895, 108069, '<td valign="top">This is great. Good story, fits the challenge perfectly, and really has me wondering. Nice one.</td>', 'This is great. Good story, fits the challenge perfectly, and really has me wondering. Nice one.', '2010-09-15 18:31:27.000000', NULL, 1),
(6163270, 908991, 108069, '<td valign="top">Very nice photo. Love the light and the silvery grey tone to it all.</td>', 'Very nice photo. Love the light and the silvery grey tone to it all.', '2010-09-15 18:31:53.000000', NULL, 1),
