(6163276, 908553, 108069, '<td valign="top">Beautiful shot. Excellent in black and white. Love the expanse of sky. Nice one.</td>', 'Beautiful shot. Excellent in black and white. Love the expanse of sky. Nice one.', '2010-09-15 18:34:22.000000', NULL, 1),
