(6165580, 909612, 83149, '<td valign="top">Nice shot and a right on the mark for the theme.</td>', 'Nice shot and a right on the mark for the theme.', '2010-09-18 19:19:35.000000', NULL, 1),
(6165581, 908757, 83149, '<td valign="top">Like the silhouette and the colors in the sky.  I think it would have been better if you were back farther from the subject so the head was not cropped and the entire silhouette was backed by the sky where the arm is now.</td>', 'Like the silhouette and the colors in the sky.  I think it would have been better if you were back farther from the subject so the head was not cropped and the entire silhouette was backed by the sky where the arm is now.', '2010-09-18 19:23:38.000000', NULL, 1),
(6165582, 909467, 83149, '<td valign="top">I like the usage of underexposure and the composition.</td>', 'I like the usage of underexposure and the composition.', '2010-09-18 19:25:55.000000', NULL, 1),
(6165585, 909510, 61396, '<td valign="top">The intriguing round thing on the right balances the rower well. The unleveled horizon adds to the mystery, as does the mist.</td>', 'The intriguing round thing on the right balances the rower well. The unleveled horizon adds to the mystery, as does the mist.', '2010-09-18 19:31:23.000000', NULL, 1),
(6165586, 908575, 83149, '<td valign="top">The underexposure does add to the image, but unfortunately the flower is much too overexposed which takes away.</td>', 'The underexposure does add to the image, but unfortunately the flower is much too overexposed which takes away.', '2010-09-18 19:33:03.000000', NULL, 1),
