(6165592, 909252, 83149, '<td valign="top">Nice image, although not much underexposure.  I see a lot of darks, but not much actual underexposure.</td>', 'Nice image, although not much underexposure.  I see a lot of darks, but not much actual underexposure.', '2010-09-18 19:39:02.000000', NULL, 1),
(6165597, 909681, 83149, '<td valign="top">Not much underexposure, I can pick out a fair amount of detail in the building.  It is dark but stil has a reasonable exposure level.</td>', 'Not much underexposure, I can pick out a fair amount of detail in the building.  It is dark but stil has a reasonable exposure level.', '2010-09-18 19:47:01.000000', NULL, 1),
(6165598, 909089, 83149, '<td valign="top">Not sure how to explain it, but I can''t decide whether I like or dislike the motion blur from the boat.  I guess in either case it draws my eye and is interesting so it is an effective element of the picture.  Great application of the theme as well.</td>', 'Not sure how to explain it, but I can''t decide whether I like or dislike the motion blur from the boat.  I guess in either case it draws my eye and is interesting so it is an effective element of the picture.  Great application of the theme as well.', '2010-09-18 19:52:53.000000', NULL, 1),
(6165600, 908917, 83149, '<td valign="top">Very overexposed with only a hint of underexposure, which doesn''t really add to the picture.</td>', 'Very overexposed with only a hint of underexposure, which doesn''t really add to the picture.', '2010-09-18 19:55:13.000000', NULL, 1),
(6165602, 909484, 83149, '<td valign="top">One of the few (maybe only) pictures in the challenge that I thought really carried the theme and had relatively dark subject.  Excellent job.</td>', 'One of the few (maybe only) pictures in the challenge that I thought really carried the theme and had relatively dark subject.  Excellent job.', '2010-09-18 19:57:58.000000', NULL, 1),
(6165603, 908544, 81362, '<td valign="top">Nice expressions. Not convincingly underexposed.</td>', 'Nice expressions. Not convincingly underexposed.', '2010-09-18 19:58:21.000000', NULL, 1),
(6165604, 908374, 83149, '<td valign="top">Great shot, but I don''t see much usage of underexposure.  A little around the eye and nose, but they are hardly noticable.</td>', 'Great shot, but I don''t see much usage of underexposure.  A little around the eye and nose, but they are hardly noticable.', '2010-09-18 20:01:42.000000', NULL, 1),
(6165606, 909452, 83149, '<td valign="top">Too blurry.</td>', 'Too blurry.', '2010-09-18 20:06:28.000000', NULL, 1),
